def scale(ingredients, from_servings, to_servings):
    factor = to_servings / from_servings
    return {name: round(amount * factor, 2)
            for name, amount in ingredients.items()}

scale({"flour_g": 250, "eggs": 2}, 4, 6)
# {'flour_g': 375.0, 'eggs': 3.0}
```

